-- PT121-S4-Q7. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT121-S4-Q7$batch03$ AND q.stimulus=$batch03$For many types of crops, hybrid strains have been developed that have been found in test plantings to produce significantly higher yields than were produced by traditional nonhybrid strains of those crops planted alongside them. However, in many parts of the world where farmers have abandoned traditional nonhybrid strains in favor of the hybrid strains, crop yields have not increased.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT121-S4-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT121-S4-Q7$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S4-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT121-S4-Q7$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$In test plantings, hybrid strains produced much higher yields than traditional strains.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Where farmers switched to hybrids, yields did not rise?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The tests and the real farms differ. If the tests were run on ideal land with ideal care, the hybrids' advantage may disappear under ordinary conditions. The test results would not carry over.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a difference between test conditions and real farming conditions.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT121-S4-Q7$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Farm size does not explain why yields failed to rise on farms that switched.$batch03$), ($batch03$B$batch03$, $batch03$Higher yields in "some areas" restates part of the test result. It does not explain why yields did not rise elsewhere.$batch03$), ($batch03$C$batch03$, $batch03$The hybrids were tested under much better conditions than most farms have. Their advantage depended on those conditions, so it did not show up on real farms.$batch03$), ($batch03$D$batch03$, $batch03$Taste and sales are not yields. This does not explain flat yields.$batch03$), ($batch03$E$batch03$, $batch03$Subsidies explain why farmers switched. They do not explain why yields stayed flat.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT121-S4-Q7$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
